import re
pattern = re.compile(r'(-|\+|\^|\s+)')

def process_kbd(text):
    parts = pattern.split(text)
    if len(parts) == 1:
        return [text]  # single key

    # Process parts to extract keys and separators
    keys = []
    separators = []

    i = 0
    while i < len(parts):
        # Handle empty string at start (standalone separator as key)
        if parts[i] == '':
            if i + 1 < len(parts):
                # Check if next is a separator - if so, empty is the key
                if i + 2 < len(parts) and parts[i+2] == '':
                    # Consecutive separators: second one is the key
                    keys.append(parts[i+1])
                    if i + 3 < len(parts):
                        separators.append(parts[i+2])
                    i += 4
                else:
                    # Single separator followed by key
                    keys.append(parts[i+1])
                    if i + 2 < len(parts):
                        separators.append(parts[i+1])
                    i += 3
            else:
                break
        else:
            # Regular key
            if parts[i]:
                keys.append(parts[i])
            if i + 1 < len(parts) and parts[i+1]:
                separators.append(parts[i+1])
            i += 2

    return keys

# Test cases
test_cases = ['-', '+', '^', 'Shift-+', 'Ctrl-C', 'Ctrl+-', '-x', 'Ctrl-Shift-x', 'x']
for test in test_cases:
    result = process_kbd(test)
    print(f'{test!r} -> {result}')
