import re
pattern = re.compile(r'(-|\+|\^|\s+)')

test_cases = ['-', '+', '^', 'Shift-+', 'Ctrl-C', 'Ctrl+-', '-x', 'Ctrl-Shift-x', 'x', 'a-b-c', '++', '+x']

def simulate_run(text):
    parts = pattern.split(text)
    if len(parts) == 1:
        return f'SKIP (single key): {text!r}'

    # Check is_multiwords_key
    if len(parts) == 3 and parts[0] == '' and parts[2] == '':
        return f'SKIP (single separator key): {text!r}'

    # Check for consecutive empty strings
    has_consecutive_empty = False
    for i in range(len(parts) - 1):
        if parts[i] == '' and parts[i + 1] == '':
            has_consecutive_empty = True
            break

    if has_consecutive_empty:
        return f'SKIP (consecutive separators are keys): {text!r}'

    # Process parts
    result = []
    while parts:
        key = parts.pop(0)
        if key:
            result.append(f'<kbd>{key}</kbd>')
        try:
            sep = parts.pop(0)
            result.append(sep)
        except IndexError:
            pass

    return ''.join(result)

for text in test_cases:
    print(f'{text!r} -> {simulate_run(text)}')
"

