# Different approach - identify keys and separators
import re
pattern = re.compile(r'(-|\+|\^|\s+)')

test_cases = ['-', '+', '^', 'Shift-+', 'Ctrl-C', 'Ctrl+-', '-x', 'Ctrl-Shift-x', 'x', 'a-b-c', '++', '+x']

def simulate_run(text):
    parts = pattern.split(text)
    if len(parts) == 1:
        return f'SKIP (single key): {text!r}'

    # Check single separator key (e.g., '-', '+', '^')
    if len(parts) == 3 and parts[0] == '' and parts[2] == '':
        return f'SKIP (single separator key): {text!r}'

    # Identify keys and separators
    # A part is a key if:
    # 1. It's at an even index (0, 2, 4, ...) and non-empty, OR
    # 2. It's at an odd index AND the previous part (even index) is empty

    keys = []
    separators = []

    i = 0
    while i < len(parts):
        if i % 2 == 0:
            # Even index - potential key position
            if parts[i]:
                keys.append(parts[i])
            # else: empty key position
        else:
            # Odd index - separator position
            # This is a separator only if the previous key position was non-empty
            # AND the next key position (if exists) is non-empty
            if parts[i]:
                if i > 0 and parts[i-1] and i+1 < len(parts) and parts[i+1]:
                    # Separator between two keys
                    separators.append(parts[i])
                elif i > 0 and not parts[i-1]:
                    # Previous was empty, this is a key
                    keys.append(parts[i])
                elif i+1 >= len(parts):
                    # End of string - this is a key
                    keys.append(parts[i])
                else:
                    # Default: treat as separator
                    separators.append(parts[i])
        i += 1

    # Now combine keys and separators
    result = []
    for idx, key in enumerate(keys):
        result.append(f'<kbd>{key}</kbd>')
        if idx < len(separators):
            result.append(separators[idx])

    return ''.join(result)

for text in test_cases:
    print(f'{text!r} -> {simulate_run(text)}')
"

